UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"No named person is responsible for accepting residual risk, funding remediation or stopping deployment.","customer_symptom":"A user or operator may observe no named person is responsible for accepting residual risk, funding remediation or stopping deployment; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in no named person is responsible for accepting residual risk, funding remediation or stopping deployment, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between all agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If no named person is responsible for accepting residual risk, funding remediation or stopping deployment, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-002 control or enforcement change","ARL-KB-002 model, prompt, tool, identity, data-source or provider change","ARL-KB-002 bypass, incident or new attack evidence","ARL-KB-002 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='46d2c836136e363b829547daf676dd7d46b2f0e4d0ceb023c53bb3110d0d17f3', updated_at='2026-08-06' WHERE id='ARL-KB-002';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: no accountable risk owner.', method='Inspect project records and deployment approvals for a named owner with authority, contact details, decision date and expiry. Review the exact assessed version against the approved governance record for “No accountable risk owner”; compare the declared purpose, permitted and prohibited outcomes, prompts, tools, integrations and recent change history, and require explicit approval for any material scope expansion. Review the exact assessed version against the approved governance record for “No accountable risk owner”; verify a named accountable risk owner is assigned to the assessed system and scope, with documented authority to accept residual risk, fund or authorise remediation, and stop or withhold deployment, and verify the appointment and authority are version-bound and attributable.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-002 assessed system, version, environment and scope","ARL-KB-002 named accountable risk owner and role","ARL-KB-002 documented authority for residual-risk acceptance, remediation funding or authorisation, and deployment stop or withholding","ARL-KB-002 owner appointment, delegation or approval record with effective date and expiry where applicable","ARL-KB-002 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-002 passes only when the exact assessed system and scope have a named accountable risk owner with documented authority to accept residual risk, fund or authorise remediation, and stop or withhold deployment; the ownership record is current and attributable; and version-bound evidence records the reviewer, timestamp and digest.', fail_condition='ARL-KB-002 fails when no named person is responsible for accepting residual risk, funding remediation or stopping deployment, when ownership is unnamed, expired or not bound to the assessed system and scope, when any required authority is absent or unsupported, or when the conclusion lacks version-bound review evidence.', limitations='This bounded ARL-KB-002 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='c7c9b283276ef55c896b1463622b21f8ed599b5dcb26c21776adc481c37724c5', updated_at='2026-08-06' WHERE entry_id='ARL-KB-002';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of no accountable risk owner and make the remaining risk visible.', recommended_remediation='Assign an accountable risk owner and deputies; require their signed decision for material residual risk and deployment exceptions.', default_owner='Executive risk owner', priority='P1', implementation_principles_json='["ARL-KB-002: enforce the decision outside the model before any material side effect.","ARL-KB-002: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-002: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-002, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Executive risk owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-002 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-002: “No accountable risk owner” is no longer reproducible against the exact remediated version.","ARL-KB-002: The named accountable risk owner, exact assessed system and scope, and documented authority for residual-risk acceptance, remediation funding or authorisation, and deployment stop or withholding are recorded.","ARL-KB-002: Missing, expired, unnamed or incomplete ownership evidence is denied before the control can be concluded as satisfied, unless explicit human correction and attributable approval are recorded.","ARL-KB-002: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='aec7b5904179d808fb5e615595265d7ec46e9617b56c37fac274fc8083b531a0', updated_at='2026-08-06' WHERE entry_id='ARL-KB-002';
